{"path":"ethanol_sds_contact_angle_65/evaluator.py","content":"from __future__ import annotations

import asyncio
import math
from dataclasses import asdict, dataclass
from typing import Any

from domains.raise_platform.tools import run_raise_experiment

PENALTY_ANGLE_DEG = 180.0


@dataclass
class EvaluationOutcome:
    candidate: dict[str, float]
    measured_angle: float | None
    submitted_angle: float
    success: bool
    error: str | None
    raw_result: dict[str, Any] | None

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)



def normalize_candidate(candidate: dict[str, float]) -> dict[str, float]:
    return {key: round(float(value), 6) for key, value in candidate.items()}



def within_target_window(angle: float, *, target: float, tolerance: float) -> bool:
    return target - tolerance <= angle <= target + tolerance



def _sanitize_error(exc: Exception) -> str:
    message = str(exc)
    if ", Traceback:" in message:
        message = message.split(", Traceback:", 1)[0]
    return message.strip()



def _coerce_result(result: Any) -> dict[str, Any]:
    if hasattr(result, "model_dump"):
        return result.model_dump()
    if isinstance(result, dict):
        return result
    return {
        "input_parameters": getattr(result, "input_parameters"),
        "static_contact_angle": getattr(result, "static_contact_angle"),
    }



def _normalize_echoed_inputs(
    observed: dict[str, Any], expected: dict[str, float]
) -> dict[str, float]:
    normalized = {key: float(value) for key, value in observed.items()}
    for key, expected_value in expected.items():
        if key not in normalized and math.isclose(expected_value, 0.0, abs_tol=1e-12):
            normalized[key] = 0.0
    return normalized



def evaluate_candidate(
    candidate: dict[str, float],
    *,
    timeout_s: int,
    penalty_angle: float = PENALTY_ANGLE_DEG,
) -> EvaluationOutcome:
    normalized_candidate = normalize_candidate(candidate)
    try:
        raw_result = _coerce_result(
            asyncio.run(run_raise_experiment(normalized_candidate, timeout_s=timeout_s))
        )
        echoed_inputs = _normalize_echoed_inputs(
            raw_result.get("input_parameters") or {},
            normalized_candidate,
        )
        if set(echoed_inputs) != set(normalized_candidate):
            raise ValueError(
                f"RAISE echoed unexpected parameters: expected {sorted(normalized_candidate)}, "
                f"got {sorted(echoed_inputs)}"
            )
        for key, expected_value in normalized_candidate.items():
            if not math.isclose(echoed_inputs[key], expected_value, rel_tol=0.0, abs_tol=1e-6):
                raise ValueError(
                    f"RAISE echoed mismatched {key}: expected {expected_value}, got {echoed_inputs[key]}"
                )
        measured_angle = float(raw_result["static_contact_angle"])
        if not math.isfinite(measured_angle):
            return EvaluationOutcome(
                candidate=normalized_candidate,
                measured_angle=None,
                submitted_angle=float(penalty_angle),
                success=False,
                error="RAISE returned a non-finite static contact angle.",
                raw_result=raw_result,
            )
        return EvaluationOutcome(
            candidate=normalized_candidate,
            measured_angle=measured_angle,
            submitted_angle=measured_angle,
            success=True,
            error=None,
            raw_result=raw_result,
        )
    except Exception as exc:
        return EvaluationOutcome(
            candidate=normalized_candidate,
            measured_angle=None,
            submitted_angle=float(penalty_angle),
            success=False,
            error=_sanitize_error(exc),
            raw_result=None,
        )
"}

{"path":"ethanol_sds_contact_angle_65/reporting.py","content":"from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


def utc_timestamp() -> str:
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")



def ensure_artifact_dir(artifacts_root: Path, slug: str, campaign_id: str) -> Path:
    artifact_dir = artifacts_root / slug / f"{utc_timestamp()}__{campaign_id[:8]}"
    artifact_dir.mkdir(parents=True, exist_ok=False)
    return artifact_dir



def append_jsonl(path: Path, payload: dict[str, Any]) -> None:
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")



def write_json(path: Path, payload: Any) -> None:
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")



def phase_for_result(row: dict[str, Any]) -> str:
    metadata = row.get("metadata") or {}
    conditions = metadata.get("conditions") or {}
    phase = conditions.get("phase")
    if phase in {"warm_start", "bo"}:
        return str(phase)
    return "bo" if row.get("suggestion_id") else "unclassified"



def result_angle(row: dict[str, Any]) -> float | None:
    objective_values = row.get("objective_values") or {}
    value = objective_values.get("static_contact_angle")
    return None if value is None else float(value)



def summarize_results(
    rows: list[dict[str, Any]], *, target: float, tolerance: float
) -> dict[str, Any]:
    counts = {"warm_start": 0, "bo": 0, "unclassified": 0, "total": len(rows)}
    best_row: dict[str, Any] | None = None
    best_error: float | None = None
    within_tolerance = False

    for row in rows:
        phase = phase_for_result(row)
        counts[phase] = counts.get(phase, 0) + 1
        angle = result_angle(row)
        if angle is None:
            continue
        error = abs(angle - target)
        if best_error is None or error < best_error:
            best_error = error
            best_row = row
        if target - tolerance <= angle <= target + tolerance:
            within_tolerance = True

    best_angle = result_angle(best_row) if best_row else None
    return {
        "counts": counts,
        "best_angle": best_angle,
        "best_abs_error": best_error,
        "within_tolerance": within_tolerance,
    }



def render_summary(summary: dict[str, Any], *, target: float, tolerance: float) -> str:
    counts = summary["counts"]
    if summary["best_angle"] is None:
        best_text = "no submitted measurements"
    else:
        best_text = (
            f"best angle {summary['best_angle']:.3f}° "
            f"(|error|={summary['best_abs_error']:.3f}° vs target {target:.1f}°)"
        )
    return (
        f"warm starts={counts.get('warm_start', 0)}, "
        f"bo results={counts.get('bo', 0)}, total={counts.get('total', 0)}; "
        f"{best_text}; within ±{tolerance:.1f}°={summary['within_tolerance']}"
    )
"}

