            angle = float(row["obj_static_contact_angle"])
            exclusion_reason = _exclusion_reason(candidate, angle)
            if exclusion_reason is not None:
                excluded.append({"result_id": result_id, "reason": exclusion_reason})
                continue
            included.append(
                {
                    "parameter_values": candidate,
