                        },
                    },
                }
            )

    summary = SeedInspectionSummary(
        source_campaign_id=source_campaign_id,
        source_export_path=str(export_path),
        total_rows=len(included) + len(excluded),
        included_rows=len(included),
        excluded_rows=len(excluded),
        excluded_result_ids=excluded,
    )
    return included, summary


def _exclusion_reason(candidate: dict[str, float], angle: float) -> str | None:
